#include <iostream>

#define LOT_SIZE 100
#define SQUARE_BAD(x) x * x
#define SQUARE(x) ((x) * (x))
#define MAX(a, b) ((a) > (b) ? (a) : (b))

int maxOf(int a, int b) {  // a function: each argument is evaluated once
    return a > b ? a : b;
}

int main() {
    std::cout << "shares in 3 lots: " << 3 * LOT_SIZE << '\n';
    std::cout << "SQUARE_BAD(1 + 2): " << SQUARE_BAD(1 + 2) << '\n';
    std::cout << "SQUARE(1 + 2): " << SQUARE(1 + 2) << '\n';

    int ask = 5;
    const int best = MAX(4, ask++);
    std::cout << "macro: best " << best << ", ask " << ask << '\n';

    int ask2 = 5;
    const int best2 = maxOf(4, ask2++);
    std::cout << "function: best " << best2 << ", ask " << ask2 << '\n';
    return 0;
}

