#include <iostream>

int main() {
#if defined(__LP64__) || defined(_WIN64)
    std::cout << "64-bit: yes\n";
#else
    std::cout << "64-bit: no\n";
#endif

#ifdef __CHAR_UNSIGNED__
    std::cout << "char: unsigned\n";
#else
    std::cout << "char: signed\n";
#endif

#if defined(_LIBCPP_VERSION)
    std::cout << "library: libc++ " << _LIBCPP_VERSION << '\n';
#elif defined(__GLIBCXX__)
    std::cout << "library: libstdc++ " << _GLIBCXX_RELEASE << '\n';
#endif

#if __cplusplus >= 201703L
    std::cout << "C++17 or newer: yes\n";
#else
    std::cout << "C++17 or newer: no\n";
#endif
    return 0;
}

