#include <iostream>

#define SHOW(expr) std::cout << #expr << " = " << (expr) << '\n'

#define CHECK(cond)                                                        \
    do {                                                                   \
        if (!(cond)) {                                                     \
            std::cout << __FILE__ << ':' << __LINE__ << ": check failed: " \
                      << #cond << " in " << __func__ << '\n';              \
        }                                                                  \
    } while (0)

void sendOrder(int qty, double price) {
    CHECK(qty > 0);
    CHECK(price > 0.0);
    std::cout << "sent " << qty << " @ " << price << '\n';
}

int main() {
    SHOW(3 * 100 + 7);
    SHOW(sizeof(double));
    sendOrder(100, 192.75);
    sendOrder(-5, 192.75);

    const bool replay = false;
    if (replay)
        CHECK(false);  // one statement, thanks to do { } while (0)
    else
        std::cout << "live mode\n";
    return 0;
}

