practice.solution:
#include <iostream>

#define TRACE(expr) std::cout << #expr << " -> " << (expr) << '\n'

#define REQUIRE(cond)                                                                 \
    do {                                                                              \
        if (!(cond)) {                                                                \
            std::cout << "REQUIRE failed in " << __func__ << ": " << #cond << '\n'; \
            return;                                                                   \
        }                                                                             \
    } while (0)

void cancelOrder(int orderId, int openOrders) {
    REQUIRE(orderId > 0);
    REQUIRE(openOrders > 0);
    std::cout << "cancelled " << orderId << '\n';
}

int main() {
    const int bid = 19270;
    const int ask = 19280;
    TRACE(ask - bid);
    TRACE(bid < ask);
    cancelOrder(42, 3);
    cancelOrder(0, 3);
    cancelOrder(7, 0);
    return 0;
}

