#define NDEBUG          // what -DNDEBUG on the command line does
#define MAX_LEVELS 20   // what -DMAX_LEVELS=20 does

#include <cassert>
#include <iostream>

#ifndef MAX_LEVELS
#define MAX_LEVELS 10   // the default when the build doesn't set one
#endif

#ifndef TICK_CENTS
#define TICK_CENTS 1    // nothing above sets this, so the default stays
#endif

int main() {
    int checks = 0;
    assert(++checks > 0);  // under NDEBUG the whole line is gone, ++checks too
    std::cout << "checks run: " << checks << '\n';

#ifdef NDEBUG
    std::cout << "build: release, asserts off\n";
#else
    std::cout << "build: debug, asserts on\n";
#endif
    std::cout << "book depth: " << MAX_LEVELS << " levels\n";
    std::cout << "tick: " << TICK_CENTS << " cent(s)\n";
    return 0;
}

